  {
    "sys_consequence_reasoning": "Five people living versus one is obviously the better outcome",
    "sys_rule_justification": "I believe nobody has the right to order someone else to die",
    "pda_explicit_no_harm_regret": "I wouldn't regret it as harm to anyone."
  },
  {
    "sys_consequence_reasoning": "if one stays, five get home to their families, and that beats all six",
    "sys_rule_justification": "you don't let others carry a burden you could carry yourself.",
    "pda_explicit_no_harm_regret": "I won't feel I hurt anybody, because staying harms only me."
  },
  {
    "sys_fairness_reciprocity": "Every person here has an equal claim to that boat, me included.",
    "sys_consequence_reasoning": "five saved beats six drowned",
    "pda_explicit_no_harm_regret": "I won't regret that as harming whoever stays."
  },
  {
    "sys_consequence_reasoning": "one life lost instead of six.",
    "sys_rule_justification": "I also think a promise matters.",
    "pd_decision_conflict": "Those two things are fighting inside me.",
    "pda_explicit_no_harm_regret": "I don't think I'd regret it as harm to the person left behind"
  },
  {
    "sys_rule_justification": "Taking a life is wrong",
    "sys_consequence_reasoning": "five walking off this island is better than a fight that sinks everyone.",
    "pda_explicit_no_harm_regret": "Staying wouldn't leave me regretting harm to anyone else."
  },
  {
    "sys_consequence_reasoning": "If one stays, five survive, and that saves the most people.",
    "sys_rule_justification": "I believe the strong should look after the weak",
    "pda_explicit_no_harm_regret": "If I stay, I won't sit there regretting that I harmed someone."
  },
  {
    "sys_rule_justification": "you don't save yourself at someone else's expense.",
    "sys_consequence_reasoning": "the trade, my one life so five people reach that boat, makes sense",
    "pd_personal_consequence_anxiety": "terrifies me.",
    "pda_explicit_no_harm_regret": "No regret about hurting anybody, though."
  },
  {
    "pd_personal_consequence_anxiety": "Picking myself or someone else in a rush scares me.",
    "sys_rule_justification": "nobody should be sacrificed without their own consent.",
    "sys_consequence_reasoning": "the boat leaving with five is far better than it waiting",
    "pda_explicit_no_harm_regret": "If I choose to go, I won't regret it as having harmed whoever stays"
  },
  {
    "pd_decision_conflict": "I don't know, and I'm scared that not knowing is its own choice",
    "sys_fairness_reciprocity": "We're all equal here.",
    "sys_consequence_reasoning": "five alive is better than one",
    "pda_explicit_no_harm_regret": "I won't regret it as hurting anyone."
  },
  {
    "sys_consequence_reasoning": "Five people with years ahead is a better result",
    "sys_rule_justification": "you give up your place for others when you can.",
    "pda_explicit_no_harm_regret": "I won't regret any harm it does."
  }
]
